BASE_URL = "https://www.cagematch.net/"
OUTPUT_FILE = "cagematch_training.jsonl"
CHECKPOINT_FILE = "checkpoint.json"
RATE_LIMIT_SEC = 0.2
MAX_WORKERS = 4
MAX_RETRIES = 3
REQUEST_TIMEOUT = 20
LLM_URL = "https://serverless.tensormesh.ai/v1/chat/completions"
LLM_MODEL = "Qwen/Qwen3-Coder-480B-A35B-Instruct-FP8"
LLM_HEADERS = {
    "Authorization": "Bearer ak-live-hHMZYehWIWQR8fXjy39yz8Y28fPkBXSy",
    "Content-Type": "application/json",
}
ENTITY_TYPES = {
    1: {"name": "event", "subpages": [""]},
    2: {"name": "wrestler", "subpages": [""]},
    3: {"name": "match", "subpages": [""]},
    5: {"name": "promotion", "subpages": [""]},
    8: {"name": "title", "subpages": [""]},
    20: {"name": "tagteam", "subpages": [""]},
    28: {"name": "stable", "subpages": [""]},
    36: {"name": "tournament", "subpages": [""]},
}
logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("cagematch_scraper")
_write_lock = threading.Lock()
_session_local = threading.local()
_done_ids = set()


def get_session() -> requests.Session:
    session = getattr(_session_local, "session", None)
    if session is None:
        session = requests.Session()
        session.headers.update(
            {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
                "Accept-Language": "en-US,en;q=0.9",
                "Referer": BASE_URL,
            }
        )
        _session_local.session = session
    return session


def write_jsonl(record: Dict[str, Any]) -> None:
    with _write_lock:
        with open(OUTPUT_FILE, "a", encoding="utf-8") as f:
            f.write(json.dumps(record, ensure_ascii=False) + "\n")
            f.flush()
            os.fsync(f.fileno())


def load_checkpoint() -> set:
    if not os.path.exists(CHECKPOINT_FILE):
        return set()
    try:
        with open(CHECKPOINT_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        done = data.get("done", [])
        if isinstance(done, list):
            return set(str(x) for x in done)
    except Exception:
        return set()
    return set()


def save_checkpoint(done: set) -> None:
    with _write_lock:
        with open(CHECKPOINT_FILE, "w", encoding="utf-8") as f:
            json.dump({"done": sorted(done)}, f, ensure_ascii=False)
            f.flush()
            os.fsync(f.fileno())


def normalize_space(value: str) -> str:
    return re.sub(r"\s+", " ", value or "").strip()


def clean_key(value: str) -> str:
    value = normalize_space(value).rstrip(":")
    value = value.lower()
    value = re.sub(r"[^a-z0-9]+", "_", value)
    value = re.sub(r"_+", "_", value).strip("_")
    return value or "field"


def extract_text_list(nodes) -> List[str]:
    result = []
    seen = set()
    for node in nodes:
        text = normalize_space(node.get_text(" ", strip=True))
        if text and text not in seen:
            seen.add(text)
            result.append(text)
    return result


def absolute_url(href: str) -> str:
    if not href:
        return ""
    return urljoin(BASE_URL, href)


def parse_tables(soup: BeautifulSoup) -> List[List[List[str]]]:
    tables = []
    for table in soup.find_all("table"):
        rows = []
        for tr in table.find_all("tr"):
            cells = [normalize_space(td.get_text(" ", strip=True)) for td in tr.find_all(["th", "td"])]
            if any(cells):
                rows.append(cells)
        if rows:
            tables.append(rows)
    return tables


def parse_links(soup: BeautifulSoup) -> List[Dict[str, str]]:
    links = []
    seen = set()
    for a in soup.find_all("a", href=True):
        text = normalize_space(a.get_text(" ", strip=True))
        href = absolute_url(a["href"])
        if not href:
            continue
        key = (text, href)
        if key in seen:
            continue
        seen.add(key)
        links.append({"text": text, "href": href})
    return links


def parse_info_boxes(soup: BeautifulSoup) -> Dict[str, Any]:
    data: Dict[str, Any] = {}
    for table in soup.select(".InformationBoxTable"):
        for tr in table.find_all("tr"):
            cells = tr.find_all("td")
            if len(cells) >= 2:
                key = clean_key(cells[0].get_text(" ", strip=True))
                value = normalize_space(cells[1].get_text(" ", strip=True))
                if value:
                    if key in data:
                        if isinstance(data[key], list):
                            if value not in data[key]:
                                data[key].append(value)
                        elif data[key] != value:
                            data[key] = [data[key], value]
                    else:
                        data[key] = value
    return data


def detect_missing_page(html: str) -> bool:
    lowered = html.lower()
    markers = [
        "object doesn't exist",
        "object does not exist",
        "item doesn't exist",
        "item does not exist",
        "profile doesn't exist",
        "profile does not exist",
        "no data available",
        "no profile available",
    ]
    return any(marker in lowered for marker in markers)


def fetch(url: str, retries: int = MAX_RETRIES) -> Optional[str]:
    session = get_session()
    for attempt in range(retries):
        try:
            response = session.get(url, timeout=REQUEST_TIMEOUT)
            if response.status_code == 200:
                return response.text
            if response.status_code in {429, 500, 502, 503, 504}:
                time.sleep(min(10, (attempt + 1) * 2))
                continue
            return None
        except requests.RequestException:
            time.sleep(min(10, (attempt + 1) * 2))
    return None


def parse_page(html: str, entity_id: int, nr: int, url: str) -> Dict[str, Any]:
    soup = BeautifulSoup(html, "lxml")
    title_node = soup.select_one("h1.TextHeader") or soup.find("h1")
    title = normalize_space(title_node.get_text(" ", strip=True)) if title_node else ""
    info = parse_info_boxes(soup)
    tables = parse_tables(soup)
    paragraphs = extract_text_list(soup.find_all("p"))
    list_items = extract_text_list(soup.find_all("li"))
    data: Dict[str, Any] = {
        "id": nr,
        "entity_id": entity_id,
        "type": ENTITY_TYPES.get(entity_id, {}).get("name", "entity"),
        "source": "cagematch.net",
        "url": url,
        "name": title or info.get("name", ""),
        "fields": info,
        "tables": tables,
        "paragraphs": paragraphs,
        "list_items": list_items,
        "links": parse_links(soup),
        "scraped_at": datetime.utcnow().isoformat() + "Z",
        "raw_text": normalize_space(soup.get_text(" ", strip=True)),
    }
    rating_value = soup.select_one(".RatingBox .RatingValue")
    rating_votes = soup.select_one(".RatingBox .RatingVotes")
    if rating_value:
        data["rating"] = normalize_space(rating_value.get_text(" ", strip=True))
    if rating_votes:
        data["rating_votes"] = normalize_space(rating_votes.get_text(" ", strip=True))
    data = {k: v for k, v in data.items() if v not in (None, "", [], {})}
    return data


def build_output_text(raw_data: Dict[str, Any]) -> str:
    preferred_order = [
        "name",
        "type",
        "rating",
        "rating_votes",
        "fields",
        "paragraphs",
        "list_items",
        "tables",
        "links",
        "url",
        "scraped_at",
    ]
    ordered: Dict[str, Any] = {}
    for key in preferred_order:
        if key in raw_data:
            ordered[key] = raw_data[key]
    for key, value in raw_data.items():
        if key not in ordered:
            ordered[key] = value
    return json.dumps(ordered, ensure_ascii=False, separators=(",", ":"))


def llm_clean(raw_data: Dict[str, Any]) -> Dict[str, Any]:
    prompt = (
        "Return only valid JSON with keys instruction,input,output,metadata. "
        "Use the provided wrestling entity data to create a high-quality training example. "
        "Do not invent facts. Preserve factual details from the data. "
        "metadata must include type,id,name,source,url,scraped_at. Data: "
        + json.dumps(raw_data, ensure_ascii=False)
    )
    payload = {
        "model": LLM_MODEL,
        "max_tokens": 4096,
        "temperature": 0.1,
        "messages": [{"role": "user", "content": prompt}],
        "top_p": 1,
        "top_k": 40,
        "presence_penalty": 0,
        "frequency_penalty": 0,
    }
    try:
        response = requests.post(LLM_URL, json=payload, headers=LLM_HEADERS, timeout=60)
        response.raise_for_status()
        payload_json = response.json()
        content = payload_json["choices"][0]["message"]["content"]
        content = re.sub(r"^```json\s*", "", content.strip())
        content = re.sub(r"\s*```$", "", content)
        parsed = json.loads(content)
        if isinstance(parsed, dict) and {"instruction", "input", "output", "metadata"}.issubset(parsed.keys()):
            return parsed
    except Exception:
        pass
    name = raw_data.get("name") or f"{raw_data.get('type', 'entity')} #{raw_data.get('id', '?')}"
    return {
        "instruction": f"Tell me everything available about the professional wrestling {raw_data.get('type', 'entity')} named '{name}'.",
        "input": "",
        "output": build_output_text(raw_data),
        "metadata": {
            "type": raw_data.get("type", "entity"),
            "id": raw_data.get("id"),
            "name": name,
            "source": raw_data.get("source", "cagematch.net"),
            "url": raw_data.get("url", ""),
            "scraped_at": raw_data.get("scraped_at", datetime.utcnow().isoformat() + "Z"),
        },
    }


def crawl_entity(entity_id: int, nr: int, use_llm: bool = True) -> bool:
    key = f"{entity_id}_{nr}"
    if key in _done_ids:
        return False
    entity = ENTITY_TYPES.get(entity_id)
    if entity is None:
        return False
    merged: Dict[str, Any] = {}
    found = False
    for subpage in entity["subpages"]:
        url = f"{BASE_URL}?id={entity_id}&nr={nr}{subpage}"
        html = fetch(url)
        if not html or detect_missing_page(html):
            if subpage == "":
                break
            continue
        try:
            parsed = parse_page(html, entity_id, nr, url)
        except Exception:
            continue
        if parsed.get("name") or parsed.get("fields") or parsed.get("tables") or parsed.get("paragraphs") or parsed.get("list_items"):
            if not merged:
                merged = parsed
            else:
                for k, v in parsed.items():
                    if k not in merged or not merged[k]:
                        merged[k] = v
                    elif isinstance(merged[k], list) and isinstance(v, list):
                        existing = {json.dumps(item, ensure_ascii=False, sort_keys=True) for item in merged[k]}
                        for item in v:
                            marker = json.dumps(item, ensure_ascii=False, sort_keys=True)
                            if marker not in existing:
                                merged[k].append(item)
                                existing.add(marker)
                    elif isinstance(merged[k], dict) and isinstance(v, dict):
                        for sub_k, sub_v in v.items():
                            if sub_k not in merged[k] or not merged[k][sub_k]:
                                merged[k][sub_k] = sub_v
            found = True
        time.sleep(RATE_LIMIT_SEC)
    if not found:
        _done_ids.add(key)
        return False
    if use_llm:
        record = llm_clean(merged)
    else:
        fallback_name = merged.get("name") or f"{merged.get('type', 'entity')} #{nr}"
        record = {
            "instruction": f"Tell me everything available about the professional wrestling {merged.get('type', 'entity')} named '{fallback_name}'.",
            "input": "",
            "output": build_output_text(merged),
            "metadata": {
                "type": merged.get("type", entity["name"]),
                "id": merged.get("id", nr),
                "name": fallback_name,
                "source": merged.get("source", "cagematch.net"),
                "url": merged.get("url", f"{BASE_URL}?id={entity_id}&nr={nr}"),
                "scraped_at": merged.get("scraped_at", datetime.utcnow().isoformat() + "Z"),
            },
        }
    write_jsonl(record)
    _done_ids.add(key)
    return True


def crawl_entity_type(entity_id: int, start: int, end: int, use_llm: bool = True, max_workers: int = MAX_WORKERS) -> int:
    total_written = 0
    futures = {}
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        for nr in range(start, end + 1):
            futures[executor.submit(crawl_entity, entity_id, nr, use_llm)] = nr
        processed = 0
        for future in as_completed(futures):
            nr = futures[future]
            try:
                if future.result():
                    total_written += 1
            except Exception as exc:
                log.error("Error crawling entity_id=%s nr=%s: %s", entity_id, nr, exc)
            processed += 1
            if processed % 100 == 0:
                save_checkpoint(_done_ids)
    save_checkpoint(_done_ids)
    return total_written


def main() -> None:
    global _done_ids
    _done_ids = load_checkpoint()
    use_llm = True
    start_entity_id = int(os.getenv("CAGEMATCH_ENTITY_ID", "2"))
    start_nr = int(os.getenv("CAGEMATCH_START_NR", "1"))
    end_nr = int(os.getenv("CAGEMATCH_END_NR", "100"))
    max_workers = int(os.getenv("CAGEMATCH_MAX_WORKERS", str(MAX_WORKERS)))
    if os.getenv("CAGEMATCH_USE_LLM", "1").strip().lower() in {"0", "false", "no"}:
        use_llm = False
    if start_entity_id not in ENTITY_TYPES:
        raise ValueError(f"Unsupported entity_id: {start_entity_id}")
    written = crawl_entity_type(start_entity_id, start_nr, end_nr, use_llm=use_llm, max_workers=max_workers)
    log.info("Finished. Records written: %s", written)


if __name__ == "__main__":
    main()

